extern "C" void hffn_compact_g4_backward_nt_f32(const float*,const float*,const float*,const float*,const int32_t*,const int32_t*,const int16_t*,const float*,const int32_t*,const int16_t*,const float*,int,int,int,float*,float*,float*,float*,float*,float*,float*,float*,float*,int64_t*);
extern "C" void hffn_compact_g4_backward_dual_nt_f32(const float*,const float*,const float*,const float*,const int32_t*,const int32_t*,const int16_t*,const float*,const int32_t*,const int16_t*,const float*,const int32_t*,const int32_t*,const int16_t*,const int32_t*,int,int,int,float*,float*,float*,float*,float*,float*,float*,float*,int64_t*);
extern "C" void hffn_compact_g4_backward_post_attention_layernorm_nt_f32(const float*,const float*,const float*,const float*,const float*,const float*,const float*,const float*,const int32_t*,const int32_t*,const int16_t*,const float*,const int32_t*,const int16_t*,const float*,int,int,int,float*,float*,float*,float*,float*,float*,float*,float*,float*,float*,float*,float*,int64_t*);
