namespace {
void ck(const torch::Tensor&t,torch::ScalarType d,const char*n){TORCH_CHECK(t.device().is_cpu()&&t.scalar_type()==d&&t.is_contiguous(),n," must be contiguous CPU tensor with expected dtype");}

void b(torch::Tensor gy,torch::Tensor xt,torch::Tensor z,torch::Tensor act,torch::Tensor groups,torch::Tensor uoff,torch::Tensor uidx,torch::Tensor up,torch::Tensor doff,torch::Tensor didx,torch::Tensor down,torch::Tensor gyt,torch::Tensor gx,torch::Tensor gxt,torch::Tensor gxlocal,torch::Tensor gz,torch::Tensor gup,torch::Tensor gdown,torch::Tensor gbup,torch::Tensor gbdown,torch::Tensor timing){
 for(auto p:{&gy,&xt,&z,&act,&up,&down,&gyt,&gx,&gxt,&gxlocal,&gz,&gup,&gdown,&gbup,&gbdown})ck(*p,torch::kFloat32,"float");for(auto p:{&groups,&uoff,&doff})ck(*p,torch::kInt32,"offset");for(auto p:{&uidx,&didx})ck(*p,torch::kInt16,"index");ck(timing,torch::kInt64,"timing");TORCH_CHECK(groups.numel()==kG4Groups+1&&uoff.numel()==z.size(0)+1&&doff.numel()==z.size(0)+1&&gup.numel()==up.numel()&&gdown.numel()==down.numel()&&timing.numel()==3,"invalid compact backward shapes");hffn_compact_g4_backward_nt_f32(gy.data_ptr<float>(),xt.data_ptr<float>(),z.data_ptr<float>(),act.data_ptr<float>(),groups.data_ptr<int32_t>(),uoff.data_ptr<int32_t>(),uidx.data_ptr<int16_t>(),up.data_ptr<float>(),doff.data_ptr<int32_t>(),didx.data_ptr<int16_t>(),down.data_ptr<float>(),(int)gy.size(0),(int)gy.size(1),(int)z.size(0),gyt.data_ptr<float>(),gx.data_ptr<float>(),gxt.data_ptr<float>(),gxlocal.data_ptr<float>(),gz.data_ptr<float>(),gup.data_ptr<float>(),gdown.data_ptr<float>(),gbup.data_ptr<float>(),gbdown.data_ptr<float>(),timing.data_ptr<int64_t>());
}

void dual_b(torch::Tensor gy,torch::Tensor xt,torch::Tensor z,torch::Tensor act,torch::Tensor groups,torch::Tensor uoff,torch::Tensor uidx,torch::Tensor up,torch::Tensor doff,torch::Tensor didx,torch::Tensor down,torch::Tensor ioff,torch::Tensor islots,torch::Tensor ihidden,torch::Tensor igroups,torch::Tensor gyt,torch::Tensor gx,torch::Tensor gxt,torch::Tensor gz,torch::Tensor gup,torch::Tensor gdown,torch::Tensor gbup,torch::Tensor gbdown,torch::Tensor timing){for(auto p:{&gy,&xt,&z,&act,&up,&down,&gyt,&gx,&gxt,&gz,&gup,&gdown,&gbup,&gbdown})ck(*p,torch::kFloat32,"dual float");for(auto p:{&groups,&uoff,&doff,&ioff,&islots,&igroups})ck(*p,torch::kInt32,"dual offset");for(auto p:{&uidx,&didx,&ihidden})ck(*p,torch::kInt16,"dual index");ck(timing,torch::kInt64,"dual timing");TORCH_CHECK(groups.numel()==kG4Groups+1&&igroups.numel()==kG4Groups+1&&uoff.numel()==z.size(0)+1&&doff.numel()==z.size(0)+1&&ioff.numel()==gy.size(1)+1&&islots.numel()==up.numel()&&ihidden.numel()==up.numel()&&timing.numel()==4,"invalid dual backward shapes");hffn_compact_g4_backward_dual_nt_f32(gy.data_ptr<float>(),xt.data_ptr<float>(),z.data_ptr<float>(),act.data_ptr<float>(),groups.data_ptr<int32_t>(),uoff.data_ptr<int32_t>(),uidx.data_ptr<int16_t>(),up.data_ptr<float>(),doff.data_ptr<int32_t>(),didx.data_ptr<int16_t>(),down.data_ptr<float>(),ioff.data_ptr<int32_t>(),islots.data_ptr<int32_t>(),ihidden.data_ptr<int16_t>(),igroups.data_ptr<int32_t>(),(int)gy.size(0),(int)gy.size(1),(int)z.size(0),gyt.data_ptr<float>(),gx.data_ptr<float>(),gxt.data_ptr<float>(),gz.data_ptr<float>(),gup.data_ptr<float>(),gdown.data_ptr<float>(),gbup.data_ptr<float>(),gbdown.data_ptr<float>(),timing.data_ptr<int64_t>());}

void post_b(torch::Tensor gout,torch::Tensor residual,torch::Tensor gamma,torch::Tensor mean,torch::Tensor invstd,torch::Tensor xt,torch::Tensor z,torch::Tensor act,torch::Tensor groups,torch::Tensor uoff,torch::Tensor uidx,torch::Tensor up,torch::Tensor doff,torch::Tensor didx,torch::Tensor down,torch::Tensor gyt,torch::Tensor gln2,torch::Tensor gxlocal,torch::Tensor gz,torch::Tensor gup,torch::Tensor gdown,torch::Tensor gbup,torch::Tensor gbdown,torch::Tensor gresidual,torch::Tensor gattn,torch::Tensor ggamma,torch::Tensor gbeta,torch::Tensor timing){
 for(auto p:{&gout,&residual,&gamma,&mean,&invstd,&xt,&z,&act,&up,&down,&gyt,&gln2,&gxlocal,&gz,&gup,&gdown,&gbup,&gbdown,&gresidual,&gattn,&ggamma,&gbeta})ck(*p,torch::kFloat32,"float");for(auto p:{&groups,&uoff,&doff})ck(*p,torch::kInt32,"offset");for(auto p:{&uidx,&didx})ck(*p,torch::kInt16,"index");ck(timing,torch::kInt64,"timing");TORCH_CHECK(gout.dim()==2&&residual.sizes()==gout.sizes()&&gamma.numel()==gout.size(1)&&mean.numel()==gout.size(0)&&invstd.numel()==mean.numel()&&groups.numel()==kG4Groups+1&&uoff.numel()==z.size(0)+1&&doff.numel()==z.size(0)+1&&timing.numel()==5,"invalid compact post-attention backward shapes");hffn_compact_g4_backward_post_attention_layernorm_nt_f32(gout.data_ptr<float>(),residual.data_ptr<float>(),gamma.data_ptr<float>(),mean.data_ptr<float>(),invstd.data_ptr<float>(),xt.data_ptr<float>(),z.data_ptr<float>(),act.data_ptr<float>(),groups.data_ptr<int32_t>(),uoff.data_ptr<int32_t>(),uidx.data_ptr<int16_t>(),up.data_ptr<float>(),doff.data_ptr<int32_t>(),didx.data_ptr<int16_t>(),down.data_ptr<float>(),(int)gout.size(0),(int)gout.size(1),(int)z.size(0),gyt.data_ptr<float>(),gln2.data_ptr<float>(),gxlocal.data_ptr<float>(),gz.data_ptr<float>(),gup.data_ptr<float>(),gdown.data_ptr<float>(),gbup.data_ptr<float>(),gbdown.data_ptr<float>(),gresidual.data_ptr<float>(),gattn.data_ptr<float>(),ggamma.data_ptr<float>(),gbeta.data_ptr<float>(),timing.data_ptr<int64_t>());
}

void adam(std::vector<torch::Tensor>up,std::vector<torch::Tensor>gup,std::vector<torch::Tensor>um,std::vector<torch::Tensor>uv,std::vector<torch::Tensor>down,std::vector<torch::Tensor>gdown,std::vector<torch::Tensor>dm,std::vector<torch::Tensor>dv,std::vector<torch::Tensor>bup,std::vector<torch::Tensor>gbup,std::vector<torch::Tensor>bum,std::vector<torch::Tensor>buv,std::vector<torch::Tensor>bdown,std::vector<torch::Tensor>gbdown,std::vector<torch::Tensor>bdm,std::vector<torch::Tensor>bdv,std::vector<int64_t>steps,double lr,double b1,double b2,double eps,double wd){size_t n=up.size();TORCH_CHECK(n&&steps.size()==n,"invalid compact AdamW tables");for(size_t i=0;i<n;++i){for(auto*t:{&up[i],&gup[i],&um[i],&uv[i],&down[i],&gdown[i],&dm[i],&dv[i],&bup[i],&gbup[i],&bum[i],&buv[i],&bdown[i],&gbdown[i],&bdm[i],&bdv[i]})ck(*t,torch::kFloat32,"AdamW");hffn_compact_g4_adamw_f32(up[i].data_ptr<float>(),gup[i].data_ptr<float>(),um[i].data_ptr<float>(),uv[i].data_ptr<float>(),(int)up[i].numel(),down[i].data_ptr<float>(),gdown[i].data_ptr<float>(),dm[i].data_ptr<float>(),dv[i].data_ptr<float>(),(int)down[i].numel(),bup[i].data_ptr<float>(),gbup[i].data_ptr<float>(),bum[i].data_ptr<float>(),buv[i].data_ptr<float>(),(int)bup[i].numel(),bdown[i].data_ptr<float>(),gbdown[i].data_ptr<float>(),bdm[i].data_ptr<float>(),bdv[i].data_ptr<float>(),(int)bdown[i].numel(),(float)lr,(float)b1,(float)b2,(float)eps,(float)wd,steps[i]);}}

}
PYBIND11_MODULE(TORCH_EXTENSION_NAME,m){m.def("backward_nt",&b);m.def("backward_dual_nt",&dual_b);m.def("backward_post_attention_layernorm_nt",&post_b);m.def("adamw_all",&adam);}
